#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY so GC keeps it alive; a raw pointer was collected mid-match (shipping crash).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker was a raw UArenaScoreTracker* without UPROPERTY(), so Unreal garbage collection did not treat it as a reference. The shipping log shows GC purging 412 objects at 21:05:13, then the first goal at 21:05:27 calls ScoreTracker->AddPoints() on the collected (dangling) pointer, causing EXCEPTION_ACCESS_VIOLATION reading 0xffffffffffffffff in UArenaScoreTracker::AddPoints() via AArenaGameMode::OnGoalScored(). In the editor the object happened to survive until play ended; packaged GC timing exposed it. Fix: mark ScoreTracker as UPROPERTY() TObjectPtr<UArenaScoreTracker> in ArenaGameMode.h so GC keeps it alive.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary is loaded at runtime via LoadObject in BeginPlay, so it has no hard reference the cooker can follow. Packaging has bCookAll=False and DirectoriesToAlwaysCook only listed /Game/Data/Effects, so the Palettes directory was never cooked into the pak. The shipping log shows 'Couldn't find file for package /Game/Data/Palettes/DA_Primary', LoadObject returns null, and the HUD falls back to gray. Fix: add +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to Config/DefaultGame.ini so the palette is cooked and loads in the packaged build."
}
